#!/usr/bin/env python3
"""Additional offline tests; depends on the unchanged original owner test fixture."""
from pathlib import Path
import runpy

ROOT = Path(__file__).resolve().parents[1]
EXTRA = '\n {\n  brightnessSchedule::Schedule s={};s.defaultTenths=1000;s.count=2;\n  s.events[0]={60,800,0};s.events[1]={1430,200,30};\n  assert(brightnessSchedule::valid(s));\n  auto pct=[&](uint32_t ms){return brightnessSchedule::percent(s,ms,true);};\n  assert(pct(1430UL*60000-1)==80.f);\n  assert(pct(1430UL*60000)==80.f);\n  assert(pct(5UL*60000)==50.f);\n  assert(pct(20UL*60000)==20.f);\n  assert(pct(20UL*60000+1)==20.f);\n  assert(pct(60UL*60000-1)==20.f);\n  assert(pct(60UL*60000)==80.f);\n  assert(pct(brightnessSchedule::DAY_MS-1)>59.99f);\n  assert(pct(0)==60.f);\n  assert(pct(brightnessSchedule::DAY_MS)==pct(0));\n  auto invalid=s;invalid.events[1].fadeMinutes=91;\n  assert(!brightnessSchedule::valid(invalid));\n  Memory mem;rt::Owner own(mem);st::Record rec={};\n  assert(own.begin()==st::Result::Missing);\n  assert(own.store().save(0,s,rec)==st::Result::Ok);\n  own.serviceLocal(0,{5UL*60000,true},false,true);\n  assert(own.current().gain==5000);\n  own.serviceLocal(1,{5UL*60000,false},false,true);\n  assert(own.current().gain==2000&&own.current().waitingForTime);\n  own.serviceLocal(2,{10UL*60000,true},false,true);\n  assert(own.current().gain==4000&&!own.current().waitingForTime);\n  own.serviceLocal(3,{10UL*60000,true},true,true);\n  assert(own.current().gain==10000&&own.current().pausedAutomatic);\n  own.serviceLocal(4,{10UL*60000,true},true,false);\n  assert(own.current().gain==0);\n }\n {\n  Memory mem;rt::Owner own(mem);own.begin();Clock c;\n  own.serviceFromClock(100,clockRead,&c,false,true);assert(c.reads==1);\n  own.serviceFromClock(149,clockRead,&c,false,true);assert(c.reads==1);\n  own.serviceFromClock(150,clockRead,&c,false,true);assert(c.reads==2);\n  own.serviceFromClock(151,clockRead,&c,true,true);assert(c.reads==3);\n  own.serviceFromClock(152,clockRead,&c,true,false);assert(c.reads==4);\n  st::Record r={};brightnessSchedule::Schedule s={};s.defaultTenths=350;\n  assert(own.store().save(0,s,r)==st::Result::Ok);\n  own.serviceFromClock(153,clockRead,&c,false,true);\n  assert(c.reads==5&&own.current().gain==3500);\n  assert(own.store().load(r)==st::Result::Ok);\n  own.serviceFromClock(154,clockRead,&c,false,true);assert(c.reads==5);\n  s.defaultTenths=450;\n  assert(own.store().save(1,s,r)==st::Result::Ok);\n  own.serviceFromClock(155,clockRead,&c,false,true);\n  assert(c.reads==6&&own.current().revision==2&&own.current().gain==4500);\n  own.serviceLocal(156,{0,false},false,true);\n  assert(own.current().gain==4500&&!own.current().waitingForTime);\n }\n {\n  Memory mem;mem.readFail=true;rt::Owner own(mem);st::Record r={};\n  assert(own.begin()==st::Result::ReadFailed);\n  for(unsigned i=0;i<3;++i){\n   assert(own.store().load(r)==st::Result::ReadFailed);\n   own.serviceLocal(i,{0,true},false,true);\n   assert(own.current().gain==0&&own.current().storageFault);\n  }\n  mem.readFail=false;\n  for(unsigned i=3;i<6;++i){\n   assert(own.store().load(r)==st::Result::Missing);\n   own.serviceLocal(i,{0,true},false,true);\n   assert(own.current().gain==0&&own.current().storageFault);\n  }\n  brightnessSchedule::Schedule s={};s.defaultTenths=300;\n  assert(own.store().save(0,s,r)==st::Result::Ok);\n  own.serviceLocal(6,{0,true},false,true);\n  assert(own.current().gain==3000&&!own.current().storageFault);\n  mem.data.clear();assert(own.store().load(r)==st::Result::Missing);\n  own.serviceLocal(7,{0,true},false,true);\n  assert(own.current().gain==3000&&own.current().storageFault);\n  st::Record restored={};restored.revision=1;restored.schedule=s;mem.data=bytes(restored);\n  assert(own.store().load(r)==st::Result::Ok);\n  own.serviceLocal(8,{0,true},false,true);\n  assert(own.current().gain==3000&&!own.current().storageFault);\n  mem.writeFail=true;\n  for(unsigned i=9;i<12;++i){\n   assert(own.store().save(1,s,r)==st::Result::WriteUncertain);\n   own.serviceLocal(i,{0,true},false,true);\n   assert(own.current().gain==3000&&own.current().revision==1&&own.current().storageFault);\n  }\n }\n'

def main():
    fixture = runpy.run_path(str(ROOT / "tests/test_brightness_schedule_runtime_owner.py"))
    original = fixture["CPP"]
    marker = " return 0;\n}\n"
    if original.count(marker) != 1:
        raise SystemExit("Original fixture main marker changed; review integration before running")
    fixture["main"].__globals__["CPP"] = original.replace(marker, EXTRA + marker)
    fixture["main"]()
    print("PASS: additional midnight/time-validity/cadence/adoption/fault edge cases")

if __name__ == "__main__":
    main()
